entries[97153] = { ["name"] = "Schatz des Donnerkönigs", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[97154] = { ["name"] = "Schlafsand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigt Sonnenhäscheransturm\n- Wohlwollend\nBenutzen: Versetzt das Ziel 25 Sek. lang in einen magisch hervorgerufenen Schlaf. Funktioniert nur bei Humanoiden und Wildtieren während des Szenarios Schatzkammer des Donnerkönigs. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[97155] = { ["name"] = "Verwandlungsschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigt Sonnenhäscheransturm\n- Ehrfürchtig\nBenutzen: Verformt mit Hilfe von Magie den Schlüssel, sodass er in jedes uralte Tor in der Zitadelle des Donnerkönigs im Szenario Schatzkammer des Donnerkönigs passt. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[97156] = { ["name"] = "Frostrunenfalle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigt Sonnenhäscheransturm\n- Respektvoll\nBenutzen: Platziert eine Rune, die das nächste gegnerische Ziel, das darauftritt, für 20 Sek. einfriert. Kann nur im Szenario Schatzkammer des Donnerkönigs eingesetzt werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[97157] = { ["name"] = "Trank des leichten Fußes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigt Sonnenhäscheransturm\n- Freundlich\nBenutzen: Kann verwendet werden, um während des Szenarios Schatzkammer des Donnerkönigs über Bodenkachelfallen zu levitieren, mit verringerter Geschwindigkeit zu fallen und sich über Wasser zu bewegen. Erlittener Schaden bricht den Effekt ab. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[97158] = { ["name"] = "Ein gewöhnlicher Stein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenötigt Stufe 90\nBenötigt Sonnenhäscheransturm\n- Wohlwollend\nBenutzen: Kann verwendet werden, um im Szenario Schatzkammer des Donnerkönigs einen Gegner abzulenken oder eine Falle zu entschärfen. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[97159] = { ["name"] = "Arkaner Treibstoff", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (60)\nBenötigt Stufe 90\nBenötigt Sonnenhäscheransturm\n- Respektvoll\nBenutzen: Verbraucht einen arkanen Fokus, um Euch vorwärts zu katapultieren. Kann nur während des Szenarios Schatzkammer des Donnerkönigs verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
