entries[98115] = { ["name"] = "Trophäenhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Die meisten Hauer scheinen von Stachelebern oder Kodos zu stammen. Manche der frischen nicht.\"\nVerkaufspreis:" }
entries[98116] = { ["name"] = "Gefriergetrocknetes Hyänenfleisch", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. 199999 Gesundheit und ( 50000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, bewegt Ihr Euch 1 Stunde lang schneller, während Ihr Euch im Nördlichen Brachland aufhaltet.\nVerkaufspreis:" }
entries[98117] = { ["name"] = "Geldbräu", ["text"] = "Einzigartig (24)\nBenutzen: Nehmt einen kräftigen Schluck von dem goldenen Gebräu. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[98118] = { ["name"] = "Knusperskorpione", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. 199999 Gesundheit und ( 50000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, verursacht Ihr 1 Stunde lang mehr Schaden, während Ihr Euch im Nördlichen Brachland aufhaltet.\nVerkaufspreis:" }
entries[98119] = { ["name"] = "Unlesbare Pläne", ["text"] = "Wird beim Aufheben gebunden\n\"Diesen wirren Kritzeleien kann man nur mit Mühe und Not entnehmen, dass es dabei irgendwie um eine Ausgrabung geht.\"\nVerkaufspreis:" }
entries[98120] = { ["name"] = "Lieferschein", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Beleg für eine große Anzahl versiegelte Behälter, die nach Orgrimmar geliefert wurden.\"\nVerkaufspreis:" }
entries[98121] = { ["name"] = "Bernsteinsamenbrötchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Waffenkunde.\n\"Aus irgendeinem Grund war es dieses Jahr schwierig, an frische Bernsteinsamen zu kommen.\"\nVerkaufspreis:" }
entries[98122] = { ["name"] = "Camembert du Grollhouffe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Tempo.\n\"Wie man vorhersagen könnte, ist es außerordentlich schwierig, einen Grollhuf zu melken.\"\nVerkaufspreis:" }
entries[98123] = { ["name"] = "Walhaikaviar", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 kritischen Trefferwert.\n\"Hat einen sehr salzigen Geschmack, ähnlich wie Tränen.\"\nVerkaufspreis:" }
entries[98124] = { ["name"] = "Blutbeerenkuchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Parieren.\n\"Blutbeeren sind eigentlich ziemlich verbreitet, nur geht heute fast keiner mehr nach Quel'Danas, um sie zu pflücken.\"\nVerkaufspreis:" }
entries[98125] = { ["name"] = "Gehobelte Zangartrüffeln", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Ausweichen.\n\"Nur ein sehr kleiner Teil der Zangartrüffel ist nicht giftig. Es ist dieser Teil.\"\nVerkaufspreis:" }
entries[98126] = { ["name"] = "Foie gras de poulet mécanique", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Trefferwert.\n\"Wir garantieren, dass dieser Robopieps human behandelt und nicht zwangsgeölt wurde.\"\nVerkaufspreis:" }
entries[98127] = { ["name"] = "Verbeulte Büchse Kaja'Cola", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Meisterschaft.\n\"Sehr schwer aufzutreiben. Es gibt davon nur noch wenige.\"\nVerkaufspreis:" }
